  [BASE + "summarize"]: summarize,
  [BASE + "dateTime"]: dateTimeV2,
  [BASE + "crypto"]: crypto,
  [BASE + "respondToWebhook"]: respondToWebhook,
  [BASE + "itemLists"]: itemLists,
  [BASE + "html"]: html,
  [BASE + "executionData"]: executionData,
